using System.Linq;
using AiLabs.Rules.Config;
using AiLabs.Rules.Core;
using AiLabs.Rules.Sim;
using AiLabs.Rules.State;
using AiLabs.Rules.Systems;
using AiLabs.SimTests.Support;
using Xunit;

namespace AiLabs.SimTests;

/// <summary>Q666–Q735: batch 15 finisher — rivals/chips closure (schema 31, grown, local).</summary>
public class HatchRivalsChipsFinisherLaterTests
{
    static ModelState Released(Game g, int cap) => new ModelState { Id = g.State.TakeId(), LineId = "mini", Capability = cap, Status = ModelStatus.Released, Alignment = 500, Name = "F" };

    static void DistressAcquire(Game g, LabState r)
    {
        r.Models.Add(Released(g, 508));
        r.Cash = -16_200;
        r.WeeksInDebt = 1;
        Finance.Earn(g.Me, LedgerLine.CapitalIn, 88_000_000);
        g.Do(Command.AcquireLab(g.Id, r.Id));
    }

    static int Hall(Game g, LabState lab)
    {
        int id = g.Do(Command.BuyLand(lab.Id, "us-oregon")).CreatedId;
        lab.Holding(id).HallKw = 450_000;
        return id;
    }

    [Fact] public void Q666_finisher_schema() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4000, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); DistressAcquire(g, r); Assert.Equal(32, g.State.Schema); }
    [Fact] public void Q667_finisher_plan_controller() { var g = Game.New(seed: 1291); var r = g.Rival("openaye"); r.Models.Add(Released(g, 524)); r.Cash = -16_600; Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_500_000); g.Do(Command.AcquireLab(g.Id, r.Id)); Assert.Equal(LabController.Plan, r.Controller); }
    [Fact] public void Q668_finisher_refuse_design() { var g = Game.New(seed: 1292); var r = g.Rival("openaye"); r.Models.Add(Released(g, 536)); r.Cash = -17_600; Finance.Earn(g.Me, LedgerLine.CapitalIn, 76_500_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.StartChipDesign(r.Id, "inference", "n28", "medium", "fp16", "ddr", "air"), CommandError.LabAbsorbed); }
    [Fact] public void Q669_finisher_roundtrip() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4500, 6)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 34_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 46_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); DistressAcquire(g, r); SaveSchemaPretend.AssertRoundTrip(g.Sim); }
    [Fact] public void Q670_finisher_event() { var g = Game.New(seed: 1294); var r = g.Rival("openaye"); r.Models.Add(Released(g, 548)); r.Cash = -18_200; Finance.Earn(g.Me, LedgerLine.CapitalIn, 79_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); Assert.Contains(g.State.Events, e => e.Kind == EventKind.LabAcquired); }
    [Fact] public void Q671_finisher_pipeline_count_671() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4100, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 2)); DistressAcquire(g, r); Assert.Equal(2, g.Me.ChipOrders[0].Count); }
    [Fact] public void Q672_finisher_refuse_tapeout_672() { var g = Game.New(seed: 1296); var r = g.Rival("openaye"); r.Models.Add(Released(g, 530)); r.Cash = -17_000; int did = g.State.TakeId(); r.ChipDesigns.Add(new ChipDesign { Id = did, Status = ChipDesignStatus.Designing, NodeId = "n28", DieId = "medium", FormatId = "fp16", MemoryId = "ddr", CoolingId = "air", Target = "inference", Version = 1, YieldPermille = 700 }); Finance.Earn(g.Me, LedgerLine.CapitalIn, 74_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.TapeOut(r.Id, did), CommandError.LabAbsorbed); }
    [Fact] public void Q673_finisher_hall_cloud_two_673() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4300, 10)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 80_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 90_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int hall = Hall(g, r); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, hall, 1)); DistressAcquire(g, r); Assert.Equal(2, g.Me.ChipOrders.Count); }
    [Fact] public void Q674_finisher_chip_sales_buy_674() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4700, 6)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 30_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 44_000_000); long s = g.Me.Ledger.Lifetime.ChipSales; g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); Assert.True(g.Me.Ledger.Lifetime.ChipSales > s); }
    [Fact] public void Q675_finisher_quote_total_675() { var g = Game.New(seed: 1299); var r = g.Rival("openaye"); r.Models.Add(Released(g, 542)); r.Cash = -17_500; Finance.Earn(g.Me, LedgerLine.CapitalIn, 77_000_000); Assert.True(AcquisitionSystem.Quote(g.C, g.State, g.Me, r).Total > 0); }
    [Fact] public void Q676_finisher_economy_participates_676() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 3900, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 54_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); DistressAcquire(g, r); Assert.True(LabQueries.ParticipatesInEconomy(g.Me)); }
    [Fact] public void Q677_finisher_delivery_tick_677() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4000, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int t = r.ChipOrders[0].DeliveryTick; DistressAcquire(g, r); Assert.Equal(t, g.Me.ChipOrders[0].DeliveryTick); }
    [Fact] public void Q678_finisher_refuse_buy_land_678() { var g = Game.New(seed: 1302); var r = g.Rival("openaye"); r.Models.Add(Released(g, 526)); r.Cash = -16_850; Finance.Earn(g.Me, LedgerLine.CapitalIn, 71_500_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.BuyLand(r.Id, "eu-ireland"), CommandError.LabAbsorbed); }
    [Fact] public void Q679_finisher_global_orders_679() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4200, 12)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 70_000_000); LabState o = HatchFollowUpLaterTests.OpenAyeBuyer(g, 80_000_000); LabState a = WorldSetup.AddRival(g.C, g.State, g.C.Rival("anthoptics"), EraSystem.AtTick(g.C, g.Tick), true); Finance.Earn(a, LedgerLine.CapitalIn, 60_000_000); g.Do(Command.BuyListedChips(o.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); g.Do(Command.BuyListedChips(a.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); int sum = g.State.Labs.Sum(l => l.ChipOrders.Count); DistressAcquire(g, o); Assert.Equal(sum, g.State.Labs.Sum(l => l.ChipOrders.Count)); }
